import { Component, effect, inject, input, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { ComiteService } from '../../services/comite.service';
import { Comite } from '../../models/sesion.model';
import { extractErrorMessage } from '../../utils/error-utils';

@Component({
  selector: 'app-comite-summary',
  imports: [RouterLink],
  templateUrl: './comite-summary.component.html',
  host: { class: 'd-block' },
})
export class ComiteSummaryComponent {
  private readonly comiteService = inject(ComiteService);

  folio = input.required<string>();

  readonly cargando = signal(true);
  readonly errorMsg = signal<string | null>(null);
  readonly comite = signal<Comite | null>(null);

  constructor() {
    effect(() => {
      const f = this.folio();
      this.cargando.set(true);
      this.errorMsg.set(null);
      this.comite.set(null);

      this.comiteService.getComite(f).subscribe({
        next: (c) => {
          this.cargando.set(false);
          this.comite.set(c);
        },
        error: (err) => {
          this.cargando.set(false);
          this.errorMsg.set(extractErrorMessage(err));
        },
      });
    });
  }

  getNivelBadgeClass(nivel: string | null): string {
    switch (nivel) {
      case 'estatal':
        return 'bg-primary';
      case 'municipal':
        return 'bg-success';
      case 'federal':
        return 'bg-info';
      default:
        return 'bg-secondary';
    }
  }
}
