import { Component, computed, effect, input, output, signal } from '@angular/core';
import { Observacion } from '../../models/observacion.model';

@Component({
  selector: 'app-campo-observable',
  templateUrl: './campo-observable.component.html',
  host: {
    class: 'd-block',
    '[id]': '"field-" + fieldId()',
    '[class.bg-warning]': 'highlighted()',
    '[class.bg-opacity-10]': 'highlighted()',
    '[class.border]': 'highlighted()',
    '[class.border-warning]': 'highlighted()',
    '[class.rounded]': 'highlighted()',
    '[class.p-2]': 'highlighted()',
  },
})
export class CampoObservableComponent {
  readonly label = input.required<string>();
  readonly value = input.required<string>();
  readonly fieldId = input.required<string>();
  readonly observaciones = input<Observacion[]>([]);
  readonly readonly = input(true);
  readonly highlighted = input(false);
  readonly modoEdicion = input(false);
  readonly modoEvaluador = input(false);
  readonly solicitudStatus = input<string>('');

  readonly valorCambiado = output<string>();
  readonly corregida = output<number>();
  readonly agregarObservacion = output<string>();

  protected readonly valorEditable = signal('');

  protected readonly hasPendientes = computed(() =>
    this.observaciones().some((o) => o.status === 'pendiente'),
  );

  protected readonly useTextarea = computed(() => this.value().length > 40);

  constructor() {
    effect(() => {
      this.valorEditable.set(this.value());
    });
  }

  onInput(event: Event): void {
    const target = event.target as HTMLInputElement | HTMLTextAreaElement;
    this.valorEditable.set(target.value);
    this.valorCambiado.emit(target.value);
  }
}
