import { Component, computed, effect, input, output, signal } from '@angular/core';
import { NuevaObservacionData, Observacion, ObservacionTarget } from '../../models/observacion.model';

@Component({
  selector: 'app-observacion-form-modal',
  templateUrl: './observacion-form-modal.component.html',
  host: { class: 'd-block' },
})
export class ObservacionFormModalComponent {
  readonly target = input.required<ObservacionTarget>();
  readonly targetLabel = input('');
  readonly editingObs = input<Observacion | null>(null);

  readonly guardar = output<NuevaObservacionData>();
  readonly cerrar = output<void>();

  protected readonly texto = signal('');

  protected readonly esEdicion = computed(() => this.editingObs() !== null);

  constructor() {
    effect(() => {
      const obs = this.editingObs();
      this.texto.set(obs ? obs.texto : '');
    });
  }

  protected onTexto(event: Event): void {
    this.texto.set((event.target as HTMLTextAreaElement | null)?.value ?? '');
  }

  protected readonly esValido = computed(() => this.texto().trim().length > 0);

  onGuardar(): void {
    if (!this.esValido()) return;
    this.guardar.emit({
      texto: this.texto().trim(),
      target: this.target(),
    });
  }

  onCerrar(): void {
    this.cerrar.emit();
  }
}
